/**
 * DVB subtitle parser and renderer exposed to JavaScript.
 */
export class DvbParser {
    free(): void;
    [Symbol.dispose](): void;
    clearCache(): void;
    feed(data: Uint8Array): number;
    findIndexAtTimestamp(time_ms: number): number;
    finishFeed(): number;
    getCueCompositionCount(index: number): number;
    getCueEndTime(index: number): number;
    getCuePageState(index: number): number;
    getCueStartTime(index: number): number;
    getEndTimestamps(): Float64Array;
    getTimestamps(): Float64Array;
    constructor();
    parse(data: Uint8Array): number;
    renderAtIndex(index: number): SubtitleFrame | undefined;
    reset(): void;
    readonly count: number;
    readonly lastRenderIssue: string;
    readonly pendingLen: number;
    readonly screenHeight: number;
    readonly screenWidth: number;
}

/**
 * PGS subtitle parser and renderer exposed to JavaScript.
 */
export class PgsParser {
    free(): void;
    [Symbol.dispose](): void;
    clearCache(): void;
    feed(data: Uint8Array): number;
    findIndexAtTimestamp(time_ms: number): number;
    finishFeed(): number;
    getCueCompositionCount(index: number): number;
    getCueCompositionState(index: number): number;
    getCueEndTime(index: number): number;
    getCuePaletteId(index: number): number;
    getCueStartTime(index: number): number;
    getTimestamps(): Float64Array;
    constructor();
    parse(data: Uint8Array): number;
    renderAtIndex(index: number): SubtitleFrame | undefined;
    reset(): void;
    readonly count: number;
    readonly lastRenderIssue: string;
    readonly pendingLen: number;
    readonly screenHeight: number;
    readonly screenWidth: number;
}

/**
 * Unified render result for both formats.
 */
export class RenderResult {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    getCompositionHeight(index: number): number;
    getCompositionRgba(index: number): Uint8Array;
    getCompositionWidth(index: number): number;
    getCompositionX(index: number): number;
    getCompositionY(index: number): number;
    readonly compositionCount: number;
    readonly screenHeight: number;
    readonly screenWidth: number;
}

/**
 * A single PGS subtitle composition element.
 */
export class SubtitleComposition {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    getRgba(): Uint8Array;
    readonly height: number;
    readonly width: number;
    readonly x: number;
    readonly y: number;
}

/**
 * Subtitle format type.
 */
export enum SubtitleFormat {
    Pgs = 0,
    VobSub = 1,
    Dvb = 2,
}

/**
 * A complete PGS subtitle frame with all compositions.
 */
export class SubtitleFrame {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    getComposition(index: number): SubtitleComposition | undefined;
    readonly compositionCount: number;
    readonly height: number;
    readonly width: number;
}

/**
 * Unified subtitle renderer for PGS, VobSub, and DVB formats.
 */
export class SubtitleRenderer {
    free(): void;
    [Symbol.dispose](): void;
    clearCache(): void;
    dispose(): void;
    findIndexAtTimestamp(time_ms: number): number;
    getCueDuration(index: number): number;
    getCueEndTime(index: number): number;
    getCueStartTime(index: number): number;
    getTimestamps(): Float64Array;
    loadDvb(data: Uint8Array): number;
    loadPgs(data: Uint8Array): number;
    loadVobSub(idx_content: string, sub_data: Uint8Array): void;
    loadVobSubMks(mks_data: Uint8Array): void;
    loadVobSubOnly(sub_data: Uint8Array): void;
    constructor();
    renderAtIndex(index: number): RenderResult | undefined;
    renderAtTimestamp(time_seconds: number): RenderResult | undefined;
    readonly count: number;
    readonly format: SubtitleFormat | undefined;
    readonly hasIdxMetadata: boolean;
    readonly language: string;
    readonly lastRenderIssue: string;
    readonly screenHeight: number;
    readonly screenWidth: number;
    readonly trackId: string;
}

/**
 * A VobSub subtitle frame.
 */
export class VobSubFrame {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    getRgba(): Uint8Array;
    readonly height: number;
    readonly screenHeight: number;
    readonly screenWidth: number;
    readonly width: number;
    readonly x: number;
    readonly y: number;
}

/**
 * VobSub subtitle parser and renderer exposed to JavaScript.
 */
export class VobSubParser {
    free(): void;
    [Symbol.dispose](): void;
    attachSubData(sub_data: Uint8Array): void;
    clearCache(): void;
    dispose(): void;
    findIndexAtTimestamp(time_ms: number): number;
    getCueDuration(index: number): number;
    getCueEndTime(index: number): number;
    getCueFilePosition(index: number): number;
    getCueStartTime(index: number): number;
    getTimestamps(): Float64Array;
    loadFromData(idx_content: string, sub_data: Uint8Array): void;
    loadFromIdx(idx_content: string): void;
    loadFromMks(mks_data: Uint8Array): void;
    loadFromSubOnly(sub_data: Uint8Array): void;
    constructor();
    renderAtIndex(index: number): VobSubFrame | undefined;
    setDebandEnabled(enabled: boolean): void;
    setDebandRange(range: number): void;
    setDebandThreshold(threshold: number): void;
    readonly count: number;
    readonly debandEnabled: boolean;
    readonly hasIdxMetadata: boolean;
    readonly hasSubData: boolean;
    readonly language: string;
    readonly lastRenderIssue: string;
    readonly screenHeight: number;
    readonly screenWidth: number;
    readonly trackId: string;
}

